def execution_payment_projection(document):
 result=deepcopy(document);paths=result['paths'];schemas=result['components']['schemas']
 if not any(n in paths for n in PATHS) and not any(n in schemas for n in SCHEMAS):return result
 for section,pins in [(paths,PATHS),(schemas,SCHEMAS)]:
  for name,pin in pins.items():
   if digest(section.pop(name,None))!=pin:raise ValueError('Exact P/P1 execution/payment transport required: '+name)
 for name,pin in CHANGED.items():
  if digest(schemas[name])!=pin:raise ValueError('Exact P/P1 addition required: '+name)
  schemas[name]=deepcopy(PREVIOUS[name])
 return result
